<script setup>
import {ref,computed,onMounted} from 'vue'
import {platformApi,PanoramaApiError} from '../lib/api'
import Icon from './Icon.vue'
import logoUrl from '../assets/logo-panorama.png'
const emit=defineEmits(['exit','notify'])
// En desarrollo, el login viene con el superadmin de prueba de .env.development.local; en producción queda vacío.
const demo=()=>import.meta.env.DEV?{email:import.meta.env.VITE_SUPERADMIN_EMAIL||'',password:import.meta.env.VITE_SUPERADMIN_PASSWORD||''}:{email:'',password:''}
const admin=ref(null),checked=ref(false),login=ref(demo()),error=ref(''),busy=ref(false)
const orgs=ref([]),query=ref(''),editing=ref(null),capacity=ref({}),history=ref(null),creating=ref(false)
const blankAccount=()=>({name:'',email:'',password:'',organizationName:'',kind:'broker'})
const account=ref(blankAccount())
const statusLabel={pilot:'Piloto',active:'Activa',suspended:'Suspendida',expired:'Vencida'}
const kindLabel={broker:'Corredora',developer:'Inmobiliaria'}
const message=e=>e instanceof PanoramaApiError?e.message:'No se pudo conectar con la API.'
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?orgs.value.filter(o=>`${o.name} ${o.ownerEmail||''}`.toLowerCase().includes(q)):orgs.value})
const totals=computed(()=>({orgs:orgs.value.length,published:orgs.value.reduce((n,o)=>n+o.subscription.used,0),leads:orgs.value.reduce((n,o)=>n+o.counts.leads,0),suspended:orgs.value.filter(o=>o.subscription.status==='suspended').length}))
async function load(){orgs.value=(await platformApi.platformOrganizations()).items}
onMounted(async()=>{try{admin.value=(await platformApi.platformSession()).admin;await load()}catch(e){if(e.status!==401)error.value=message(e)}finally{checked.value=true}})
async function signIn(){busy.value=true;error.value='';try{admin.value=(await platformApi.platformLogin(login.value.email.trim(),login.value.password)).admin;login.value.password='';await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function signOut(){try{await platformApi.platformLogout()}catch{}admin.value=null;orgs.value=[];login.value=demo()}
function edit(o){editing.value=o.id;history.value=null;capacity.value={limit:o.subscription.limit,status:o.subscription.status,reason:''}}
async function saveCapacity(o){busy.value=true;try{orgs.value=(await platformApi.platformCapacity(o.id,{...capacity.value,limit:Number(capacity.value.limit)})).items;editing.value=null;emit('notify',`Cupo de ${o.name} actualizado.`)}catch(e){emit('notify',message(e))}finally{busy.value=false}}
async function showHistory(o){editing.value=null;try{history.value={id:o.id,items:(await platformApi.platformChanges(o.id)).items}}catch(e){emit('notify',message(e))}}
async function createAccount(){busy.value=true;try{await platformApi.platformCreateOrganization({...account.value,email:account.value.email.trim()});emit('notify',`Cuenta creada: ${account.value.organizationName}.`);account.value=blankAccount();creating.value=false;await load()}catch(e){emit('notify',message(e))}finally{busy.value=false}}
const when=iso=>new Intl.DateTimeFormat('es-CL',{dateStyle:'medium',timeStyle:'short'}).format(new Date(iso))
</script>
<template><div class="platform">
<header class="platform-top"><img class="brand-logo" :src="logoUrl" alt="Panorama Inmobiliario" width="186" height="44"><span class="platform-badge">SUPERADMIN</span><span class="platform-spacer"></span><template v-if="admin"><span class="muted">{{admin.name}}</span><button class="text-button" @click="signOut">Salir</button></template><button class="text-button" @click="$emit('exit')">Ir al portal<Icon name="arrow"/></button></header>
<main id="main" class="platform-main">
<section v-if="!admin" class="panel login-panel"><span class="eyebrow">ADMINISTRACIÓN DE LA PLATAFORMA</span><h1>Superadmin</h1><p v-if="!checked">Comprobando tu sesión…</p>
<form v-else @submit.prevent="signIn"><p>Acceso exclusivo para la administración de Panorama. Las cuentas de corredoras no sirven aquí.</p><p v-if="login.email&&login.email===demo().email" class="notice">Entorno local: superadmin de prueba precargado.</p><div v-if="error" class="error" role="alert">{{error}}</div><label>Correo<input v-model="login.email" type="email" required autocomplete="username"></label><label>Contraseña<input v-model="login.password" type="password" required autocomplete="current-password"></label><button class="button primary" type="submit" :disabled="busy">{{busy?'Ingresando…':'Ingresar'}}<Icon name="arrow"/></button></form></section>
<template v-else>
<div class="dashboard-heading"><div><span class="eyebrow">PANORAMA INMOBILIARIO · PLATAFORMA</span><h1>Todas las cuentas, en perspectiva.</h1><p>Corredoras e inmobiliarias, sus cupos y su actividad.</p></div><button class="button primary" @click="creating=!creating"><Icon name="plus"/>Nueva cuenta</button></div>
<div class="metrics"><article><span>Cuentas</span><strong>{{totals.orgs}}<Icon name="people"/></strong><small>Corredoras e inmobiliarias</small></article><article><span>Avisos publicados</span><strong>{{totals.published}}<Icon name="home"/></strong><small>En todo el portal</small></article><article><span>Consultas recibidas</span><strong>{{totals.leads}}<Icon name="people"/></strong><small>Suma de todas las cuentas</small></article><article><span>Suspendidas</span><strong>{{totals.suspended}}<Icon name="close"/></strong><small>Sin avisos visibles</small></article></div>
<form v-if="creating" class="panel form-grid" @submit.prevent="createAccount"><h2 class="full">Nueva cuenta</h2><label>Nombre de la organización<input v-model="account.organizationName" required minlength="2" maxlength="150"></label><label>Tipo<select v-model="account.kind"><option value="broker">Corredora</option><option value="developer">Inmobiliaria</option></select></label><label>Persona administradora<input v-model="account.name" required minlength="2" maxlength="100"></label><label>Correo de acceso<input v-model="account.email" type="email" required></label><label class="full">Contraseña inicial<input v-model="account.password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"><small>Entre 12 y 72 caracteres. Comunícala por un canal seguro. La cuenta parte con cupo piloto de 5 avisos.</small></label><div class="modal-actions full"><button type="button" class="button secondary" @click="creating=false">Cancelar</button><button class="button primary" type="submit" :disabled="busy">Crear cuenta</button></div></form>
<section class="panel"><div class="panel-heading"><h2>Cuentas</h2><label class="input-icon"><Icon name="search"/><input v-model="query" aria-label="Buscar cuentas" placeholder="Buscar por nombre o correo"></label></div>
<div class="table-wrap"><table class="platform-table"><thead><tr><th>Organización</th><th>Estado</th><th>Cupo</th><th>Avisos</th><th>Consultas</th><th>Desde</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody>
<template v-for="o in filtered" :key="o.id"><tr><td><strong>{{o.name}}</strong><small>{{kindLabel[o.kind]||o.kind}} · {{o.ownerEmail||'sin dueño'}}</small></td><td><span class="badge" :class="'status-'+o.subscription.status">{{statusLabel[o.subscription.status]||o.subscription.status}}</span></td><td>{{o.subscription.used}} / {{o.subscription.limit}}</td><td>{{o.counts.properties}}</td><td>{{o.counts.leads}}</td><td>{{when(o.createdAt)}}</td><td class="row-actions"><button class="text-button" @click="edit(o)">Cupo y estado</button><button class="text-button" @click="showHistory(o)">Historial</button></td></tr>
<tr v-if="editing===o.id" class="row-detail"><td colspan="7"><form class="capacity-form" @submit.prevent="saveCapacity(o)"><label>Publicaciones activas<input v-model="capacity.limit" type="number" min="0" max="100000" required></label><label>Estado<select v-model="capacity.status"><option v-for="(label,key) in statusLabel" :key="key" :value="key">{{label}}</option></select></label><label class="grow">Motivo (queda registrado)<input v-model="capacity.reason" required minlength="5" maxlength="300" placeholder="Ej. Contrato plan Profesional"></label><button class="button primary" type="submit" :disabled="busy">Guardar</button><button type="button" class="button secondary" @click="editing=null">Cancelar</button></form><small>No se puede bajar el cupo por debajo de los avisos publicados. Suspender oculta todos sus avisos del portal.</small></td></tr>
<tr v-if="history?.id===o.id" class="row-detail"><td colspan="7"><p v-if="!history.items.length" class="muted">Sin cambios administrativos registrados.</p><ul v-else class="history"><li v-for="(h,i) in history.items" :key="i"><strong>{{when(h.created_at)}}</strong> · {{h.old_limit}} → {{h.new_limit}} cupos · {{statusLabel[h.old_status]||h.old_status}} → {{statusLabel[h.new_status]||h.new_status}} · {{h.reason}} <small>({{h.actor||'sin registro'}})</small></li></ul><button class="text-button" @click="history=null">Cerrar historial</button></td></tr></template>
</tbody></table></div><p v-if="!filtered.length" class="empty">No hay cuentas que coincidan.</p></section>
</template></main></div></template>
